arguments.command:
python3 -I - <<'PY'
import json, glob, collections
zw=collections.Counter(); src=collections.Counter(); examples={}
for p in sorted(glob.glob('/workspace/outputs/grpo/rollouts/*.jsonl')):
    for line in open(p):
        r=json.loads(line); gt=r['gts']
        if any(not c.isprintable() and not c.isspace() for c in gt):
            zw[gt]+=1; examples.setdefault(gt,r)
print('unique contaminated ground truths',len(zw),'rollouts',sum(zw.values()))
for gt,n in zw.most_common():
    print(repr(gt),n,'codepoints',[f'U+{ord(c):04X}' for c in gt if not c.isprintable()])
# all inputs to source mapping via exact problem substring, if available in pool
pool=[json.loads(l) for l in open('/workspace/data/pool_clean.jsonl')]
match=collections.Counter()
for gt,r in examples.items():
    hits=[x for x in pool if str(x.get('answer','')).strip()==gt]
    match.update(x.get('src') for x in hits)
print('contaminated answer source counts (unique pool records):',match)
PY

